"""Synthetic dataset configuration and named presets."""

from __future__ import annotations

from dataclasses import asdict, dataclass

from prepay import periods

GENERATOR_VERSION = "1.0.0"


@dataclass(frozen=True, slots=True)
class SyntheticConfig:
    """Everything that determines the generated bytes (together with the code version).

    Attributes:
        seed: root seed; each (vintage, block) gets an independent child stream.
        first_vintage / last_vintage: origination years to generate (inclusive).
        loans_per_vintage: loans in each full vintage; the cutoff-year vintage is pro-rated.
        cutoff: last performance month (``YYYY-MM``), the synthetic "performance cutoff date".
        release: SFLLD release whose layout the files follow.
        anomalies: inject documented data-quality anomalies (recorded in the manifest).
        block_size: loans simulated together; bounds memory, part of the deterministic recipe.
    """

    seed: int = 20261028
    first_vintage: int = 2003
    last_vintage: int = 2026
    loans_per_vintage: int = 250
    cutoff: str = "2026-06"
    release: int = 48
    anomalies: bool = True
    block_size: int = 2000

    def __post_init__(self) -> None:
        if not 1999 <= self.first_vintage <= self.last_vintage:
            raise ValueError("vintages must satisfy 1999 <= first_vintage <= last_vintage")
        if periods.year_of(self.cutoff_month) != self.last_vintage:
            raise ValueError("last_vintage must be the cutoff year (a partial vintage)")
        if self.loans_per_vintage < 20:
            raise ValueError("loans_per_vintage must be >= 20 so every anomaly kind can occur")
        if self.block_size < 1:
            raise ValueError("block_size must be positive")

    @property
    def cutoff_month(self) -> int:
        return periods.parse_iso(self.cutoff)

    def loans_in(self, vintage: int) -> int:
        """Loan count for a vintage; the cutoff year is proportional to its elapsed months."""
        if vintage < self.last_vintage:
            return self.loans_per_vintage
        elapsed = periods.month_of_year(self.cutoff_month)
        return max(20, self.loans_per_vintage * elapsed // 12)

    def as_dict(self) -> dict[str, object]:
        return {**asdict(self), "generator_version": GENERATOR_VERSION}


PRESETS = {
    # Small enough for every CI run (~6k loans, ~0.4M loan-months).
    "ci": SyntheticConfig(),
    # Clean data for model-recovery experiments: more loans, no anomalies.
    "dev": SyntheticConfig(loans_per_vintage=2000, anomalies=False),
    # Sample-scale volume (50k loans per full vintage from 1999), clean, for resource benchmarks.
    "benchmark": SyntheticConfig(
        first_vintage=1999, loans_per_vintage=50_000, block_size=5000, anomalies=False
    ),
}
